<?php
declare(strict_types=1);
session_start();
require_once __DIR__.'/../config.php';
require_once __DIR__.'/../lib/session_login_admin.php';
require_once __DIR__.'/../lib/OrderService.php';
require_once __DIR__.'/../lib/csrf_token.php';

$allowed=['Pending','Processing','Success','Error','Partial'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 $oid=trim((string)($_POST['oid']??''));$next=(string)($_POST['status']??'');
 try{
  if($oid===''||!in_array($next,$allowed,true))throw new InvalidArgumentException('Status order tidak valid.');
  $q=$conn->prepare("SELECT status FROM pembelian_digital WHERE oid=? LIMIT 1");if(!$q)throw new RuntimeException('Database tidak dapat menyiapkan query.');$q->bind_param('s',$oid);$q->execute();$q->store_result();if($q->num_rows!==1){$q->close();throw new RuntimeException('Order tidak ditemukan.');}$q->bind_result($old);$q->fetch();$q->close();
  if($next==='Error'&&!in_array($old,['Error','Success'],true))(new OrderService($conn))->markFailed($oid,'Order ditandai gagal oleh admin.');
  elseif($next!=='Error'){
   $s=$conn->prepare("UPDATE pembelian_digital SET status=? WHERE oid=? AND status<>'Success'");$s->bind_param('ss',$next,$oid);if(!$s->execute())throw new RuntimeException('Status gagal diperbarui.');$s->close();
   $map=['Pending'=>'pending','Processing'=>'processing','Success'=>'success','Partial'=>'processing'];$s=$conn->prepare("UPDATE provider_orders_v2 SET status=? WHERE local_order_id=?");if($s){$mapped=$map[$next];$s->bind_param('ss',$mapped,$oid);$s->execute();$s->close();}
  }
  $_SESSION['hasil']=['alert'=>'success','judul'=>'Order diperbarui','pesan'=>'Status '.htmlspecialchars($oid,ENT_QUOTES,'UTF-8').' → '.htmlspecialchars($next,ENT_QUOTES,'UTF-8')];
 }catch(Throwable $e){$_SESSION['hasil']=['alert'=>'danger','judul'=>'Gagal','pesan'=>htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8')];}
 header('Location: /admin-dashboard/digital');exit;
}
$search=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$limit=min(100,max(10,(int)($_GET['limit']??25)));$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*$limit;$where=[];$types='';$params=[];
if($search!==''){$where[]='oid LIKE ?';$types.='s';$params[]='%'.$search.'%';}if($status!==''&&in_array($status,$allowed,true)){$where[]='status=?';$types.='s';$params[]=$status;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$c=$conn->prepare("SELECT COUNT(*) FROM pembelian_digital{$whereSql}");if($types)$c->bind_param($types,...$params);$c->execute();$c->bind_result($total);$c->fetch();$c->close();$pages=max(1,(int)ceil($total/$limit));
$sql="SELECT oid,provider_oid,user,date,time,layanan,target,harga,status,provider,refund FROM pembelian_digital{$whereSql} ORDER BY id DESC LIMIT ? OFFSET ?";$s=$conn->prepare($sql);$bt=$types.'ii';$bp=$params;$bp[]=$limit;$bp[]=$offset;$s->bind_param($bt,...$bp);$s->execute();$s->store_result();$s->bind_result($oid,$providerOid,$user,$date,$time,$layanan,$target,$harga,$rowStatus,$provider,$refund);
require_once __DIR__.'/../lib/header_admin.php';
?>
<div class="p4-page"><section class="p4-hero"><div class="p4-eyebrow">Order Center</div><h1 class="p4-title">Order Digital</h1><p class="p4-subtitle">Pantau transaksi, provider, status dan refund dari satu halaman.</p></section><div class="p4-stat-grid"><div class="p4-card p4-stat"><div class="p4-stat-label">Total</div><div class="p4-stat-number"><?=number_format((int)$total)?></div></div><div class="p4-card p4-stat"><div class="p4-stat-label">Success</div><div class="p4-stat-number"><?=number_format(panel_db_count($conn,'pembelian_digital',"status='Success'"))?></div></div><div class="p4-card p4-stat"><div class="p4-stat-label">Processing</div><div class="p4-stat-number"><?=number_format(panel_db_count($conn,'pembelian_digital',"status='Processing'"))?></div></div><div class="p4-card p4-stat"><div class="p4-stat-label">Pending</div><div class="p4-stat-number"><?=number_format(panel_db_count($conn,'pembelian_digital',"status='Pending'"))?></div></div></div><div class="p4-card p4-panel"><form method="get" class="p4-toolbar"><div class="p4-search"><input class="form-control p4-input" name="q" value="<?=htmlspecialchars($search,ENT_QUOTES,'UTF-8')?>" placeholder="Cari Order ID..."><select class="form-control p4-select" name="status"><option value="">Semua status</option><?php foreach($allowed as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="p4-btn p4-btn-primary" type="submit">Cari</button></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Order</th><th>Pengguna</th><th>Layanan</th><th>Target</th><th>Harga</th><th>Provider</th><th>Status</th><th>Refund</th><th>Aksi</th></tr></thead><tbody><?php while($s->fetch()):?><tr><td><b><?=htmlspecialchars($oid)?></b><br><small><?=htmlspecialchars((string)$providerOid)?></small></td><td><?=htmlspecialchars($user)?></td><td><?=htmlspecialchars($layanan)?></td><td><code><?=htmlspecialchars($target)?></code></td><td><b>Rp <?=number_format((int)$harga,0,',','.')?></b></td><td><?=htmlspecialchars(strtoupper($provider))?></td><td><span class="badge badge-<?= $rowStatus==='Success'?'success':($rowStatus==='Error'?'danger':($rowStatus==='Processing'?'info':'warning')) ?>" style="border-radius:9px;padding:7px 9px"><?=htmlspecialchars($rowStatus)?></span></td><td><?=$refund?'Ya':'Tidak'?></td><td><form method="post" class="d-flex" style="gap:5px"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars((string)($config['csrf_token']??''),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="oid" value="<?=htmlspecialchars($oid,ENT_QUOTES,'UTF-8')?>"><select name="status" class="form-control form-control-sm" style="min-width:110px"><?php foreach($allowed as $x):?><option <?=$rowStatus===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Simpan</button></form></td></tr><?php endwhile;if($total===0):?><tr><td colspan="9"><div class="p4-empty"><h4>Tidak ada order</h4><p class="p4-muted">Coba ubah filter pencarian.</p></div></td></tr><?php endif;?></tbody></table></div><div class="d-flex justify-content-between mt-3"><small>Halaman <?=$page?> / <?=$pages?></small><div><?php if($page>1):?><a class="btn btn-sm btn-light" href="?q=<?=urlencode($search)?>&status=<?=urlencode($status)?>&limit=<?=$limit?>&page=<?=$page-1?>">‹</a><?php endif;?> <?php if($page<$pages):?><a class="btn btn-sm btn-primary" href="?q=<?=urlencode($search)?>&status=<?=urlencode($status)?>&limit=<?=$limit?>&page=<?=$page+1?>">›</a><?php endif;?></div></div></div></div>
